// ============================================================
// DYNAMICALLY BUILD SLACK MODAL PAYLOAD WITH ACTIVE CLIENTS
// ============================================================
const triggerId = $('Slash Command Log Change').item.json.body.trigger_id;
const channelId = $('Slash Command Log Change').item.json.body.channel_id;

const clientOptions = $input.all().map(item => {
  const name = item.json.client_name;
  return {
    text: { type: 'plain_text', text: name },
    value: name
  };
});

const view = {
  type: 'modal',
  callback_id: 'log_campaign_change',
  private_metadata: channelId,
  title: { type: 'plain_text', text: 'Log Campaign Change' },
  submit: { type: 'plain_text', text: 'Submit' },
  close: { type: 'plain_text', text: 'Cancel' },
  blocks: [
    {
      type: 'input',
      block_id: 'client_block',
      dispatch_action: true,
      element: {
        type: 'static_select',
        action_id: 'client_select',
        placeholder: { type: 'plain_text', text: 'Select client' },
        options: clientOptions
      },
      label: { type: 'plain_text', text: 'Client Name' }
    },
    {
      type: 'input',
      block_id: 'category_block',
      element: {
        type: 'static_select',
        action_id: 'category_select',
        placeholder: { type: 'plain_text', text: 'Select category' },
        options: [
          { text: { type: 'plain_text', text: 'Subject Line' }, value: 'Subject Line' },
          { text: { type: 'plain_text', text: 'Body Copy' }, value: 'Body Copy' },
          { text: { type: 'plain_text', text: 'ICP Target' }, value: 'ICP Target' },
          { text: { type: 'plain_text', text: 'Sender Account' }, value: 'Sender Account' }
        ]
      },
      label: { type: 'plain_text', text: 'Change Category' }
    },
    {
      type: 'input',
      block_id: 'description_block',
      element: {
        type: 'plain_text_input',
        action_id: 'description_input',
        multiline: true,
        placeholder: { type: 'plain_text', text: 'What changed, why, and expected impact...' }
      },
      label: { type: 'plain_text', text: 'Description of Change' }
    }
  ]
};

return [{ json: { trigger_id: triggerId, view: view } }];

