// ============================================================
// PARSE NESTED SLACK INTERACTION SUBMISSION PAYLOAD
// ============================================================
const rawPayload = $json.raw_body.payload;
const payload = JSON.parse(rawPayload);
const values = payload.view.state.values;
const callbackId = payload.view.callback_id;
const username = payload.user.name || 'unknown_analyst';
const channelId = payload.view.private_metadata || null;

if (callbackId === 'log_campaign_change') {
  const clientName = values.client_block.client_select.selected_option.value;
  const category = values.category_block.category_select.selected_option.value;
  const description = values.description_block.description_input.value;

  let campaignSelections = [];
  const multiSelected = values.campaign_multi_block && values.campaign_multi_block.campaign_multi_select && values.campaign_multi_block.campaign_multi_select.selected_options;
  if (multiSelected && multiSelected.length > 0) {
    campaignSelections = multiSelected.map(opt => {
      const parts = opt.value.split('::');
      return { platform: parts[0], campaign_id: parts[1], campaign_name: parts[2] };
    });
  } else if (values.campaign_fallback_block) {
    const campaignNameFree = (values.campaign_fallback_block.campaign_fallback_input.value || '').trim() || 'Unspecified Campaign';
    const platformFallback = (values.platform_fallback_block && values.platform_fallback_block.platform_fallback_select && values.platform_fallback_block.platform_fallback_select.selected_option) ? values.platform_fallback_block.platform_fallback_select.selected_option.value : 'general';
    campaignSelections = [{
      platform: platformFallback,
      campaign_id: 'campaign_' + platformFallback + '_' + campaignNameFree.toLowerCase().replace(/\s+/g, '_'),
      campaign_name: campaignNameFree
    }];
  }

  return campaignSelections.map(sel => ({
    json: {
      callback_id: callbackId,
      client_name: clientName,
      campaign_id: sel.campaign_id,
      campaign_name: sel.campaign_name,
      platform: sel.platform,
      change_category: category,
      change_description: description,
      actioned_by: username,
      channel_id: channelId
    }
  }));
} else if (callbackId === 'log_bulk_context') {
  const results = [];
  Object.keys(values).forEach(blockId => {
    if (blockId.startsWith('context_block_')) {
      const clientName = blockId.replace('context_block_', '');
      const val = values[blockId].context_input.value;
      if (val && val.trim()) {
        results.push({
          json: {
            callback_id: callbackId,
            client_name: clientName,
            campaign_id: 'campaign_context_' + clientName.toLowerCase(),
            platform: 'general',
            change_category: 'Campaign Context',
            change_description: val.trim(),
            actioned_by: username,
            channel_id: channelId
          }
        });
      }
    }
  });
  return results;
} else if (callbackId === 'onboard_client_modal') {
  const clientName = values.client_name_block.client_name_input.value.trim().toUpperCase();
  const slackChannel = values.slack_channel_block.slack_channel_input.value.trim();
  const instantlyApiKey = values.instantly_api_key_block.instantly_api_key_input.value ? values.instantly_api_key_block.instantly_api_key_input.value.trim() : null;
  const heyreachApiKey = values.heyreach_api_key_block.heyreach_api_key_input.value ? values.heyreach_api_key_block.heyreach_api_key_input.value.trim() : null;

  return [{  json: {
      callback_id: callbackId,
      client_name: clientName,
      slack_channel: slackChannel,
      instantly_api_key: instantlyApiKey,
      heyreach_api_key: heyreachApiKey,
      is_active: true,
      actioned_by: username,
      channel_id: channelId
    }
  }];
}

return [];

