// ============================================================
// DYNAMICALLY BUILD SLACK BULK CONTEXT MODAL PAYLOAD
// ============================================================
const triggerId = $('Slash Command Log Context').item?.json?.body?.trigger_id;
const channelId = $('Slash Command Log Context').item?.json?.body?.channel_id;

const clients = $input.all();
const blocks = [
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text: "📝 *Log Weekly Strategic Context for Active Clients*\nProvide strategic context (e.g., body copy A/B tests, sequence pauses, target audience changes) for the AI report. Leave fields blank for clients that do not have updates."
    }
  },
  {
    type: "divider"
  }
];

clients.forEach(item => {
  const clientName = item.json.client_name;
  blocks.push({
    type: "input",
    block_id: "context_block_" + clientName,
    optional: true,
    element: {
      type: "plain_text_input",
      action_id: "context_input",
      multiline: true,
      placeholder: {
        type: "plain_text",
        text: "Any updates on pause status, new messaging tests, etc..."
      }
    },
    label: {
      type: "plain_text",
      text: "Context for " + clientName
    }
  });
});

const view = {
  type: 'modal',
  callback_id: 'log_bulk_context',
  private_metadata: channelId,
  title: {
    type: 'plain_text',
    text: 'Log Strategic Context'
  },
  submit: {
    type: 'plain_text',
    text: 'Submit'
  },
  close: {
    type: 'plain_text',
    text: 'Cancel'
  },
  blocks: blocks
};

return [{ json: { trigger_id: triggerId, view: view } }];

const rawPayload = $json.body.payload;
const payload = JSON.parse(rawPayload);
const interactionType = payload.type;
const view = payload.view || {};
const callbackId = view.callback_id;
const action = (payload.actions && payload.actions[0]) || null;
const actionId = action ? action.action_id : null;
const selectedClient = (actionId === 'client_select' && action.selected_option) ? action.selected_option.value : null;

const clientBlockDef = (view.blocks || []).find(b => b.block_id === 'client_block');
const clientOptions = (clientBlockDef && clientBlockDef.element && clientBlockDef.element.options) || [];

return [{
  json: {
    interaction_type: interactionType,
    callback_id: callbackId,
    action_id: actionId,
    selected_client: selectedClient,
    view_id: view.id,
    view_hash: view.hash,
    private_metadata: view.private_metadata,
    client_options: clientOptions,
    raw_body: $json.body
  }
}];

const envelope = $('Parse Interaction Envelope').item.json;
const clientName = envelope.selected_client;
const viewId = envelope.view_id;
const hash = envelope.view_hash;
const privateMetadata = envelope.private_metadata;
const clientOptions = envelope.client_options || [];

const rows = $input.all().map(i => i.json);

const isUnknown = (v) => !v || String(v).trim().toLowerCase() === 'unknown_campaign' || String(v).trim().toLowerCase() === 'unknown campaign';

const byId = {};
for (const row of rows) {
  const id = row.campaign_id;
  if (!id) continue;
  if (isUnknown(row.campaign_id) || isUnknown(row.campaign_name)) continue;
  if (!byId[id] || (row.reporting_window_end > byId[id].reporting_window_end)) {
    byId[id] = row;
  }
}
const campaigns = Object.values(byId);

const platformLabel = (p) => p === 'instantly' ? 'Instantly' : (p === 'heyreach' ? 'HeyReach' : p);

let campaignBlock;
let extraBlocks = [];
if (campaigns.length > 0) {
  const options = campaigns.map(c => ({
    text: { type: 'plain_text', text: ('[' + platformLabel(c.platform) + '] ' + c.campaign_name).slice(0, 75) },
    value: (c.platform + '::' + c.campaign_id + '::' + c.campaign_name).slice(0, 150)
  }));
  campaignBlock = {
    type: 'input',
    block_id: 'campaign_multi_block',
    element: {
      type: 'multi_static_select',
      action_id: 'campaign_multi_select',
      placeholder: { type: 'plain_text', text: 'Select campaign(s)' },
      options: options
    },
    label: { type: 'plain_text', text: 'Campaign(s)' }
  };
} else {
  campaignBlock = {
    type: 'input',
    block_id: 'campaign_fallback_block',
    element: {
      type: 'plain_text_input',
      action_id: 'campaign_fallback_input',
      placeholder: { type: 'plain_text', text: 'e.g. Q3 Outbound Push' }
    },
    label: { type: 'plain_text', text: 'Campaign Name (no synced campaigns yet - enter manually)' }
  };
  extraBlocks.push({
    type: 'input',
    block_id: 'platform_fallback_block',
    element: {
      type: 'static_select',
      action_id: 'platform_fallback_select',
      placeholder: { type: 'plain_text', text: 'Select platform' },
      options: [
        { text: { type: 'plain_text', text: 'Instantly (Email)' }, value: 'instantly' },
        { text: { type: 'plain_text', text: 'HeyReach (LinkedIn)' }, value: 'heyreach' },
        { text: { type: 'plain_text', text: 'General / Both' }, value: 'general' }
      ]
    },
    label: { type: 'plain_text', text: 'Platform' }
  });
}

const view = {
  type: 'modal',
  callback_id: 'log_campaign_change',
  private_metadata: privateMetadata,
  title: { type: 'plain_text', text: 'Log Campaign Change' },
  submit: { type: 'plain_text', text: 'Submit' },
  close: { type: 'plain_text', text: 'Cancel' },
  blocks: [
    {
      type: 'input',
      block_id: 'client_block',
      dispatch_action: true,
      element: {
        type: 'static_select',
        action_id: 'client_select',
        placeholder: { type: 'plain_text', text: 'Select client' },
        options: clientOptions,
        initial_option: clientOptions.find(o => o.value === clientName)
      },
      label: { type: 'plain_text', text: 'Client Name' }
    },
    campaignBlock,
    ...extraBlocks,
    {
      type: 'input',
      block_id: 'category_block',
      element: {
        type: 'static_select',
        action_id: 'category_select',
        placeholder: { type: 'plain_text', text: 'Select category' },
        options: [
          { text: { type: 'plain_text', text: 'Subject Line' }, value: 'Subject Line' },
          { text: { type: 'plain_text', text: 'Body Copy' }, value: 'Body Copy' },
          { text: { type: 'plain_text', text: 'ICP Target' }, value: 'ICP Target' },
          { text: { type: 'plain_text', text: 'Sender Account' }, value: 'Sender Account' }
        ]
      },
      label: { type: 'plain_text', text: 'Change Category' }
    },
    {
      type: 'input',
      block_id: 'description_block',
      element: {
        type: 'plain_text_input',
        action_id: 'description_input',
        multiline: true,
        placeholder: { type: 'plain_text', text: 'What changed, why, and expected impact...' }
      },
      label: { type: 'plain_text', text: 'Description of Change' }
    }
  ]
};

return [{ json: { view_id: viewId, hash: hash, view: view } }];

const items = $('Parse Slack Interaction').all().map(i => i.json);
if (items.length === 0) return [];

const callbackId = items[0].callback_id;

if (callbackId === 'log_campaign_change') {
  const first = items[0];
  const lines = items.map(it => `• [${it.platform}] ${it.campaign_name || it.campaign_id}`).join('\n');
  const text = `:memo: *Campaign change logged in Supabase \`campaign_change_logs\` table successfully!*\n\n*Client Name:* \`${first.client_name}\`\n*Campaigns Logged:*\n${lines}\n*Category:* \`${first.change_category}\`\n*Description:* \`${first.change_description}\`\n*Actioned By:* \`${first.actioned_by}\``;
  return [{ json: { channel_id: first.channel_id, text } }];
}

return items.map(it => {
  const label = it.change_category === 'Campaign Context' ? ':bulb: *Strategic context logged in Supabase `campaign_change_logs` table successfully!*' : ':memo: *Campaign change logged in Supabase `campaign_change_logs` table successfully!*';
  const text = `${label}\n\n*Client Name:* \`${it.client_name}\`\n*Category:* \`${it.change_category}\`\n*Description:* \`${it.change_description}\`\n*Actioned By:* \`${it.actioned_by}\``;
  return { json: { channel_id: it.channel_id || '#test-outbound-reporting', text } };
});
